  ep58ModelExplain: "Para invitar a alguien, pregunta “Would you like to…?” o “Do you want to…?”",
  ep58ComprehensionInstruction: "Escucha. ¿Qué se está proponiendo?",
  ep58CompOptCorrect: "Hacer algo juntos el sábado.",
  ep58CompOptWrong1: "Quedar para hablar de trabajo.",
  ep58CompOptWrong2: "Algo que ya pasó.",
  ep58OrderInstruction: "Pon las palabras en orden.",
  ep58BlankInstruction: "Completa la palabra que falta.",
  ep58BlankHint: "Es la misma palabra con la que empieza “Would you like…?”",
  ep58OpenInstruction: "Invita a Lingua a hacer algo.",
  ep58ListenInstruction: "Escucha la respuesta. ¿Sobre qué se está preguntando?",
  ep58AgainInstruction: "Invita a Lingua a hacer otra cosa, otro día.",
  ep58FinalInstruction: "Una vez más, sin ayuda: invita a alguien a hacer algo.",
  ep58CloseTitle: "Invitación enviada",
  ep58CloseBody: "Ya puedes abrir una conversación con una invitación, no solo responder a una.",
  ep59Title: "Me encantaría, pero…",
  ep59Goal: "Acepta una invitación, o recházala con una razón.",
  ep59CanDoName: "Aceptar o rechazar con una razón",
  ep59Duration: "10 min",
  ep59RecallInstruction: "Recuerda: ¿cómo invitas a alguien a hacer algo?",
  ep59SceneTitle: "Respondiendo con sinceridad",
