  ep59Start: "Vamos",
  ep59ModelExplain: "Acepta con “Yes, I'd like that!” Rechaza con “I'd love to, but…” más una razón: nunca solo “no”.",
  ep59ComprehensionInstruction: "Escucha. ¿Es una aceptación o un rechazo?",
  ep59CompOptCorrect: "Un rechazo, pero educado, con una razón.",
  ep59CompOptWrong1: "Un sí claro.",
  ep59CompOptWrong2: "Una pregunta, no una respuesta.",
  ep59BlankInstruction: "Completa la palabra que falta.",
  ep59BlankHint: "¿Cuál es la razón para decir que no?",
  ep59ChoiceInstruction: "¿Cuál es un rechazo?",
  ep59AcceptInstruction: "Acepta la invitación.",
  ep59DeclineInstruction: "No puedes ir. Rechaza, y di por qué.",
  ep59InsistInstruction: "Están preguntando otra vez, sobre otro día. Responde una vez más.",
  ep59FinalInstruction: "Una vez más, sin ayuda: rechaza, con una razón.",
  ep59CloseTitle: "Respondido con sinceridad",
  ep59CloseBody: "Ya puedes aceptar o rechazar una invitación, y un rechazo siempre viene con una razón.",
  ep60Title: "Y entonces…",
  ep60Goal: "Sigue la conversación después de acordar el plan.",
  ep60CanDoName: "Mantener una conversación más larga",
  ep60Duration: "10 min",
  ep60RecallInstruction: "Recuerda: ¿cómo rechazas una invitación, con una razón?",
  ep60SceneTitle: "Aún no del todo",
  ep60SceneBody: "El plan ya casi está hecho, pero la conversación no ha terminado del todo.",
  ep60Start: "Vamos",
  ep60ModelExplain: "Enlaza dos ideas con “and”, “but” o “so”: un turno, dos pensamientos conectados.",
  ep60ComprehensionInstruction: "Escucha. ¿Qué dos ideas se están conectando?",
  ep60CompOptCorrect: "Que le gusta la idea, y que necesita mirar la hora.",
  ep60CompOptWrong1: "Dos ideas separadas, sin relación.",
  ep60CompOptWrong2: "Una sola idea, repetida dos veces.",
  ep60MeaningInstruction: "No entiendes una palabra que Lingua usó. ¿Qué preguntas?",
  ep60BlankInstruction: "Completa el conector que falta.",
  ep60BlankHint: "Enlaza dos ideas que no encajan del todo.",
  ep60OpenInstruction: "Acepta la invitación, y añade un pensamiento relacionado.",
  ep60ConnectInstruction: "El tema acaba de cambiar. Responde, y conecta tu respuesta con lo que se acaba de decir.",
  ep60FinalInstruction: "Una vez más, sin ayuda: mantén dos ideas conectadas en un turno.",
  ep60CloseTitle: "Conversación mantenida",
  ep60CloseBody: "Ya puedes seguir hablando después de la primera respuesta, conectando una idea con la siguiente.",
  ep61Title: "Hagamos otra cosa",
  ep61Goal: "Mantén toda una conversación para hacer un plan, sin ayuda, incluyendo un cambio de plan.",
  ep61CanDoName: "Aceptar o rechazar con una razón",
  ep61Duration: "14 min",
  ep61RecallInstruction: "Antes de empezar: sin mirar atrás, ¿qué hiciste últimamente?",
  ep61SceneTitle: "Un plan más",
