  ep61ComprehensionInstruction: "Escucha: hay una complicación. ¿Qué ha pasado?",
  ep61CompOptCorrect: "El cine está cerrado.",
  ep61CompOptWrong1: "El plan está confirmado.",
  ep61CompOptWrong2: "Nada ha cambiado.",
  ep61StoryInstruction: "Aquí tienes toda la conversación, desde la invitación hasta la confirmación.",
  ep61AdaptInstruction: "La idea original no ha salido bien. ¿Qué dices?",
  ep61ProposeInstruction: "¿Qué dices ahora? Propón algo.",
  ep61ConnectInstruction: "El tema acaba de cambiar. Responde, y conecta tu respuesta con lo que se acaba de decir.",
  ep61ConfirmInstruction: "Confirma el plan.",
  ep61CloseInstruction: "Cierra la conversación con calidez.",
  ep61FinalInstruction: "Sin mirar atrás: ¿cuál fue el plan completo, de principio a fin?",
  ep61CloseTitle: "A2 completado",
  ep61CloseBody: "Abriste una conversación que nadie te preparó, rechazaste una que de verdad no podías aceptar, y seguiste hablando más allá del primer “no”. Eso es comunicación conectada y cotidiana.",
  ep61CloseCta: "Terminar",
  ep49Title: "Gira a la izquierda, y luego…",
