  b1Ep14Title: "Problema resuelto",
  b1Ep14Goal: "Plantear un problema y negociar una solución, de principio a fin.",
  b1Ep14CanDoName: "Resolver un problema, de principio a fin",
  b1Ep14Duration: "10 min",
  b1Ep14SceneTitle: "Una conversación completa",
  b1Ep14SceneBody: "Una vez más: esta vez, todo junto: el problema, la solución y mantener la educación.",
  b1Ep14ModelExplain: "Una negociación real avanza del problema, a la petición de una solución, hasta un cierre educado.",
  b1Ep14OpenInstruction: "Plantea tu propio problema, de principio a fin.",
  b1Ep14ComprehensionInstruction: "¿Qué debería venir justo después de plantear un problema, para resolverlo de verdad?",
  b1Ep14CompOptCorrect: "Pedir una solución concreta",
  b1Ep14CompOptWrong1: "Nada, el problema ya está claro",
  b1Ep14CompOptWrong2: "Hacer una pregunta sin relación",
  b1Ep14OpenInstruction2: "Ahora negocia una solución a ese mismo problema, completamente por tu cuenta.",
  b1RetryPromptProblemEmpty: "Dime qué está mal, y qué esperabas en su lugar.",
  b1PraiseProblemIndependent: "Genial: un problema claro, con lo que esperabas.",
  b1PraiseProblemHelped: "Bien: eso nombra el problema y lo que se esperaba.",
  b1RetryExplainProblemExpectation: "Bien: ahora di qué esperabas en su lugar.",
  b1RetryPromptProblemExpectation: "Añade qué esperabas, o pediste, en su lugar.",
  b1RetryExplainProblemStatement: "Dijiste qué esperabas, pero no qué está mal: prueba con “there's a problem with...”.",
  b1RetryPromptProblemStatement: "Empieza con “there's a problem with...”.",
  b1RetryExplainProblemHarsh: "Intenta decirlo con un poco más de calma: la persona que te ayuda no es la culpable.",
  b1RetryPromptProblemHarsh: "Inténtalo de nuevo, con un poco más de educación.",
  b1PraiseFrustrationIndependent: "Perfecto: mostraste que estabas frustrado, pero seguiste siendo colaborativo.",
  b1PraiseFrustrationHelped: "Bien: eso se mantiene educado mientras muestra frustración.",
  b1RetryExplainFrustrationDetail: "Buen tono: ahora añade qué salió mal exactamente.",
  b1RetryPromptFrustrationDetail: "Di cuál es el problema exactamente.",
  b1RetryExplainFrustrationMarker: "Nombraste el problema, pero no cómo te sientes: prueba con “this isn't ideal, but...”.",
  b1RetryPromptFrustrationMarker: "Añade “this isn't ideal, but...” o “I understand, but...”.",
  b1RetryPromptNegotiateEmpty: "Pide una solución: un reemplazo, un reembolso, cualquier cosa que ayude.",
  b1PraiseNegotiateIndependent: "Genial: una negociación real y educada.",
  b1PraiseNegotiateHelped: "Bien: eso pide una solución con educación.",
  b1RetryExplainNegotiateSpeechAct: "Eso es una oferta para comprar algo nuevo, no una petición de solución: prueba con “would it be possible to...”.",
  b1RetryExplainNegotiateDemand: "Eso funciona, pero suena a exigencia: prueba con una fórmula más suave, como “would it be possible to...”.",
  b1RetryExplainNegotiateUnderdeveloped: "Buen comienzo: ahora conviértelo en una petición completa y educada, como “would it be possible to...” o “could I possibly...”.",
  b1RetryPromptNegotiateFrame: "Prueba con “would it be possible to...” o “could I possibly...”.",
  b1Ep15Title: "Cuál es el plan",
  b1Ep15Goal: "Elegir correctamente entre una decisión espontánea, un plan y una predicción.",
  b1Ep15CanDoName: "Hablar de planes e intenciones",
  b1Ep15Duration: "10 min",
  b1Ep15SceneTitle: "Tres tipos de futuro",
  b1Ep15SceneBody: "Ya conoces una forma de hablar del futuro. Ahora vamos a distinguir entre una decisión, un plan y una predicción.",
  b1Ep15ModelExplain: "“I'll” es una decisión tomada en este momento; “I'm going to” es un plan hecho con anterioridad; “will” también sirve para predecir.",
  b1Ep15ComprehensionInstruction: "¿Qué oración es un plan decidido antes de ahora, y no una decisión tomada en este instante?",
