  b1Ep15OpenInstruction: "Decide ahora mismo, y di qué vas a tomar.",
  b1Ep15OpenInstruction2: "Cuéntame un plan que ya hayas hecho.",
  b1Ep15OpenInstruction3: "Haz una predicción sobre el clima de mañana.",
  b1Ep16Title: "Algún día",
  b1Ep16Goal: "Decir qué esperas o quieres hacer en el futuro, sin una fecha fija.",
  b1Ep16CanDoName: "Hablar de esperanzas y ambiciones",
  b1Ep16Duration: "8 min",
  b1Ep16SceneTitle: "Más allá del calendario",
  b1Ep16SceneBody: "Un plan tiene una fecha. Una esperanza no: hablemos también de esas.",
  b1Ep16ModelExplain: "“I hope to”, “I'd like to” y “one day I'll” hablan todas de una esperanza, no de un plan programado.",
